.od-result{min-width:0;margin:0;border:1px solid var(--od-line);background:var(--od-muted);border-radius:var(--radius-control);padding:var(--space-2);color:var(--od-ink)}
.od-alert{margin:0;padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-control);color:var(--od-ink);background:var(--od-muted)}
.od-alert--warning{background:var(--od-warning-bg);border-color:var(--od-warning-border);color:var(--od-warning-ink)}
.od-alert--error{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-disclosure{min-width:0;margin:0;border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-paper);color:var(--od-ink)}
/* All trusted disclosures use the same centered header, marker and type scale.
 * Keep the lighter --flat and emphasis-only --info variants on this one component. */
.od-disclosure>summary{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);min-height:44px;padding:var(--space-2) var(--space-3);list-style:none;cursor:pointer;font-size:var(--od-body-size);line-height:1.5;font-weight:650;color:var(--od-ink);overflow-wrap:anywhere}
.od-disclosure>summary::-webkit-details-marker{display:none}
.od-disclosure>summary::before{content:"";flex:none;width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(-45deg)}
.od-disclosure[open]>summary::before{transform:rotate(45deg)}
.od-disclosure>summary>*{min-width:0}
.od-disclosure>summary>span:only-child{flex:1 1 0}
.od-disclosure>summary :is(strong,b){font-size:inherit;font-weight:inherit;color:inherit}
.od-disclosure[open]>summary{border-bottom:1px solid var(--od-line)}
/* One hover contract for every trusted first-level disclosure. */
.od-disclosure>summary:hover{background:var(--od-muted)}
.od-disclosure:not([open])>summary:hover{border-radius:var(--radius-surface)}
.od-disclosure[open]>summary:hover{border-radius:var(--radius-surface) var(--radius-surface) 0 0}
/** Allow 100%-width form fields inside a disclosure without their 12px margins
 * pushing their right edge outside a narrow Side Panel. */
.od-disclosure>:not(summary){min-width:0;max-width:calc(100% - var(--space-3) - var(--space-3));margin:var(--space-2) var(--space-3) 0}
.od-disclosure>:last-child:not(summary){margin-bottom:var(--space-3)}
.od-disclosure--info>summary{color:var(--od-brand)}
.od-disclosure--info[open]>summary{background:var(--od-muted)}
.od-disclosure--flat{border:0;border-radius:0;background:transparent}
.od-disclosure--flat>summary{min-height:36px;padding:var(--space-2) 0;font-size:var(--od-note-size);color:var(--od-sub)}
.od-disclosure--flat[open]>summary{border-bottom:1px solid var(--od-line);background:transparent}
.od-disclosure--flat>:not(summary){max-width:100%;margin:var(--space-2) 0 0}
.od-disclosure--flat>:last-child:not(summary){margin-bottom:0}
/* Technical disclosures stay frameless, including hover treatment. */
.od-disclosure--flat:is(:not([open]),[open])>summary:hover{background:var(--od-muted);border-radius:var(--radius-control)}
.od-segmented{display:flex;width:max-content;max-width:100%;gap:2px;padding:3px;background:var(--od-muted);border:1px solid var(--od-input-border);border-radius:var(--radius-surface)}
.od-segmented>button{min-height:32px;border-radius:var(--radius-control)}

/* Collapsible rows are interactive controls, including nested technical details. */
@media(pointer:coarse){.od-disclosure>summary{min-height:44px}}

.qa-app{width:100%;min-width:0;max-width:760px;margin-inline:auto;padding:var(--space-3)}
.qa-app [hidden]{display:none!important}
.qa-app h1,.qa-app h2{margin:0;font-size:15px}
