.qa-manage summary{font-weight:600;cursor:pointer}
.qa-import-actions{flex-wrap:wrap;margin-top:var(--space-2)}
.qa-import-actions select{flex:1 1 180px}
.qa-import-actions button{flex:none}
.qa-review{padding:var(--space-3);border:1px solid var(--od-line);border-radius:8px;background:var(--od-muted);margin-bottom:var(--space-3)}
.qa-review p{white-space:pre-wrap;overflow-wrap:anywhere}
.qa-review .qa-row{justify-content:flex-end}
.qa-app :focus-visible{outline:2px solid var(--od-focus);outline-offset:2px}
@media(max-width:350px){.qa-app{padding:var(--space-2)}.qa-card{padding:var(--space-2)}.qa-query-actions{flex-wrap:wrap}.qa-query-actions button{margin-left:auto}}

